-- Create "webforms" table
CREATE TABLE "webforms" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "description" text NULL, "confirmation" text NULL, "confirmation_url" character varying NOT NULL DEFAULT '', "submit_label" character varying NOT NULL DEFAULT '', "closed" boolean NOT NULL DEFAULT false, "notify_email" character varying NOT NULL DEFAULT '', "limit_per_user" boolean NOT NULL DEFAULT false, "max_submissions" bigint NOT NULL DEFAULT 0, "closes_at" timestamptz NULL, "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "webforms_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "webforms_nid" to table: "webforms"
CREATE UNIQUE INDEX "webforms_nid" ON "webforms" ("nid");
-- Create "webform_elements" table
CREATE TABLE "webform_elements" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "machine_name" character varying NOT NULL, "type" character varying NOT NULL, "label" character varying NOT NULL, "description" text NULL, "required" boolean NOT NULL DEFAULT false, "options" text NULL, "weight" bigint NOT NULL DEFAULT 0, "visible_if_element" character varying NOT NULL DEFAULT '', "visible_if_value" character varying NOT NULL DEFAULT '', "prefill_param" character varying NOT NULL DEFAULT '', "webform_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "webform_elements_webforms_elements" FOREIGN KEY ("webform_id") REFERENCES "webforms" ("id") ON DELETE CASCADE);
-- Create index "webform_elements_key" to table: "webform_elements"
CREATE UNIQUE INDEX "webform_elements_key" ON "webform_elements" ("webform_id", "machine_name");
-- Create "webform_submissions" table
CREATE TABLE "webform_submissions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "remote_ip" character varying NOT NULL DEFAULT '', "source_url" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "webform_id" bigint NOT NULL, "user_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "webform_submissions_webforms_submissions" FOREIGN KEY ("webform_id") REFERENCES "webforms" ("id") ON DELETE CASCADE, CONSTRAINT "webform_submissions_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE SET NULL);
-- Create index "webformsubmission_webform_id_created_at" to table: "webform_submissions"
CREATE INDEX "webformsubmission_webform_id_created_at" ON "webform_submissions" ("webform_id", "created_at");
-- Create index "webformsubmission_user_id" to table: "webform_submissions"
CREATE INDEX "webformsubmission_user_id" ON "webform_submissions" ("user_id");
-- Create "webform_submission_values" table
CREATE TABLE "webform_submission_values" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "delta" bigint NOT NULL DEFAULT 0, "value" text NOT NULL, "element_id" bigint NOT NULL, "submission_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "webform_submission_values_webform_elements_values" FOREIGN KEY ("element_id") REFERENCES "webform_elements" ("id") ON DELETE CASCADE, CONSTRAINT "webform_submission_values_webform_submissions_values" FOREIGN KEY ("submission_id") REFERENCES "webform_submissions" ("id") ON DELETE CASCADE);
-- Create index "webformsubmissionvalue_element_id" to table: "webform_submission_values"
CREATE INDEX "webformsubmissionvalue_element_id" ON "webform_submission_values" ("element_id");
-- Create index "webformsubmissionvalue_submission_id" to table: "webform_submission_values"
CREATE INDEX "webformsubmissionvalue_submission_id" ON "webform_submission_values" ("submission_id");
